"""PL-02 smoke: the volatility pipeline runs end to end on the mdata.load_prices fake.

Checks shape only (type, tickers, lengths, flags); the golden cases check values.
"""

from __future__ import annotations

import pytest

from risk import VolSeries, vol_pipeline


@pytest.fixture
def fake_loader(monkeypatch, contract_fake):
    fake = contract_fake("mdata.load_prices")
    monkeypatch.setattr(vol_pipeline, "load_prices", fake.load_prices)


@pytest.mark.usefixtures("fake_loader")
def test_vol_series_runs_on_the_fake_and_keeps_shape():
    vol = vol_pipeline.vol_series("ignored.csv", window=2)

    assert isinstance(vol, VolSeries)
    assert vol.annualized is True
    assert vol.window == 2
    assert vol.returns.tickers == ("AAA", "BBB")
    assert vol.returns.base_date == "2024-01-02"
    assert len(vol.returns.dates) == 5
    assert set(vol.values) == {"AAA", "BBB"}
    assert all(len(series) == 5 for series in vol.values.values())


@pytest.mark.usefixtures("fake_loader")
def test_vol_series_narrows_to_requested_tickers():
    vol = vol_pipeline.vol_series("ignored.csv", window=2, tickers=["BBB"])

    assert vol.returns.tickers == ("BBB",)
    assert set(vol.values) == {"BBB"}


@pytest.mark.usefixtures("fake_loader")
def test_vol_series_rejects_a_window_below_two():
    with pytest.raises(ValueError, match="window"):
        vol_pipeline.vol_series("ignored.csv", window=1)


@pytest.mark.usefixtures("fake_loader")
def test_vol_series_passes_a_missing_ticker_error_through():
    with pytest.raises(KeyError, match="ZZZ"):
        vol_pipeline.vol_series("ignored.csv", tickers=["ZZZ"])

